def sustained_breakeven(rows: list[dict], after: int) -> int | None:
    """First month after `after` from which net burn stays at or below zero to month 36."""
    found = None
    for r in reversed(rows):
        if r["month"] <= after or r["burn_usd"] > 0:
            break
        found = r["month"]
    return found

